
import pandas as pd
from sklearn.metrics import (
    average_precision_score,
    roc_auc_score,
    classification_report,
    confusion_matrix
)

# Load predictions generated by the existing model
df = pd.read_csv("outputs/churn_test_predictions.csv")

# Actual label: 1 = churned, 0 = returned
y_true = df["actual_churn"]

# Model's estimated probability of churn
churn_probability = df["churn_risk_probability"]

# Check the class distribution
print("===== TEST DATA DISTRIBUTION =====")
print(y_true.value_counts())
print("\nChurn percentage:", round(y_true.mean() * 100, 2), "%")

# Evaluate ranking performance
print("\n===== MODEL METRICS =====")
print(
    "Average precision:",
    round(average_precision_score(y_true, churn_probability), 4)
)
print(
    "ROC-AUC:",
    round(roc_auc_score(y_true, churn_probability), 4)
)

# Evaluate the model's existing predictions
print("\n===== CLASSIFICATION REPORT =====")
print(
    classification_report(
        y_true,
        df["predicted_churn"],
        labels=[0, 1],
        target_names=["Returned", "Churned"],
        zero_division=0
    )
)

print("\n===== CONFUSION MATRIX =====")
print("Rows = actual; columns = predicted")
print(confusion_matrix(y_true, df["predicted_churn"], labels=[0, 1]))

# Examine customers most likely to return
df["return_probability"] = 1 - churn_probability
top_returners = df.nlargest(500, "return_probability")

print("\n===== TOP 500 LIKELY RETURNERS =====")
print("Customers:", len(top_returners))
print(
    "Actual return rate:",
    round((top_returners["actual_churn"] == 0).mean() * 100, 2),
    "%"
)
print(
    "Actual returners:",
    int((top_returners["actual_churn"] == 0).sum())
)

# Compare with the overall return rate
print(
    "Overall return rate:",
    round((y_true == 0).mean() * 100, 2),
    "%"
)
